"""Base exporter interfaces for workflow generation."""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from pathlib import Path

from ..types import GwaithWorkflow


@dataclass
class GwaithExportResult:
    """Paths generated by an exporter."""

    manifest: str
    master_script: str
    node_scripts: dict[str, str]
    finalize_scripts: dict[str, str]


class GwaithExporter(ABC):
    """Base class for workflow exporters."""

    @abstractmethod
    def export(self, workflow: GwaithWorkflow, workflow_dir: Path) -> GwaithExportResult:
        """Export a workflow to disk."""
        raise NotImplementedError
